console.log([...it]); // [1, 2, 3, 4, 5, 6, 7, 8, 9] ... const it = Iterator.concat(array, set);
console.log([...it]); // [1, "two", 3, true, {}] ... const it = Iterator.concat(nonIterable); // TypeError: object is not iterable ... const it = Iterator.concat(arrayIterator); // No error ... const it = Iterator.concat(Iterator.from(nonIterable)); // No error ... The Iterator.concat () static method creates a new Iterator object from a list of iterable objects. The new iterator yields the values from each of the input iterables in sequence.

