    const emitter = worker as unknown as EventEmitter;
    emitter.once("message", ({ ok, result, error }: { ok: boolean; result: T; error?: string }) => {
      if (ok) resolve(result);
      else reject(new Error(`Plugin "${pluginPath}" ${stage} hook: ${error}`));
    });

